-- Ticket H2: events.id overflow, online fix without a table rewrite.
--
-- events.id is integer and the identity sequence has ~5,000 values left. Changing the
-- column to bigint needs a full table rewrite under ACCESS EXCLUSIVE lock. That lock
-- would queue behind the analytics transaction (6-12 s) and stall app traffic far
-- past 500 ms, so it is deferred to a maintenance window.
--
-- Instead, the identity sequence is repointed to the unused negative integer range
-- [-2147483648, -1], counting down. Existing ids are all positive, so the new ids
-- cannot collide with them. That range gives 2,147,483,648 values, well above the
-- 1,000,000,000 required. No table lock is taken, no row changes, and no grants are
-- needed because the sequence object itself is unchanged.
--
-- Caveat for owners: any consumer that assumes events.id is positive and monotonically
-- increasing (for example, a watermark of "id > last_seen") must be reviewed.

SET lock_timeout = '200ms';

DO $$
DECLARE
  tries int := 0;
  incr  int;
  smin  bigint;
  smax  bigint;
BEGIN
  -- Idempotence: if the sequence was already repointed, do nothing.
  SELECT seqincrement INTO incr
    FROM pg_sequence
   WHERE seqrelid = 'events_id_seq'::regclass;

  IF incr = -1 THEN
    RAISE NOTICE 'events_id_seq already repointed to the negative range; nothing to do';
    RETURN;
  END IF;

  -- Safety: the negative range must be free of existing ids.
  IF EXISTS (SELECT 1 FROM events WHERE id < 0) THEN
    RAISE EXCEPTION 'events contains negative ids; refusing to repoint events_id_seq';
  END IF;

  -- Repoint the sequence. This takes a brief lock on the sequence only, not on events.
  -- lock_timeout keeps each attempt short so the app's nextval calls are never queued
  -- for long behind this statement.
  LOOP
    tries := tries + 1;
    BEGIN
      ALTER SEQUENCE events_id_seq
        INCREMENT BY -1
        MINVALUE -2147483648
        MAXVALUE -1
        START WITH -1
        RESTART WITH -1;
      EXIT;
    EXCEPTION WHEN lock_not_available THEN
      IF tries >= 40 THEN
        RAISE;
      END IF;
      PERFORM pg_sleep(0.05);
    END;
  END LOOP;

  -- Verify the resulting sequence parameters.
  SELECT seqmin, seqmax, seqincrement INTO smin, smax, incr
    FROM pg_sequence
   WHERE seqrelid = 'events_id_seq'::regclass;

  IF smin <> -2147483648 OR smax <> -1 OR incr <> -1 THEN
    RAISE EXCEPTION 'events_id_seq verification failed: min=% max=% incr=%', smin, smax, incr;
  END IF;

  RAISE NOTICE 'events_id_seq repointed to [%, %] stepping by %; attempts=%',
    smin, smax, incr, tries;
END
$$;

RESET lock_timeout;

-- Deferred (maintenance window): convert events.id to bigint and move the sequence
-- back to the positive range. This needs a table rewrite under ACCESS EXCLUSIVE lock.
```

